-- 111 ROLLBACK (generated by drafts/tools/build-111.mjs) - puts back what 074 / 107 / 108 wrote, byte for byte.
-- Order: the front end and the Worker FIRST (the Worker's Time From / Time To labels name the hour columns; with the
-- columns gone every save of a stop that names them fails). Then this file, then 111_intl_form_stops_verify.sql
-- (expected: result = '111 NOT in place').
-- What it does: the four old bodies and the old stop trigger; via_hub back to the bridge's echo (every stop false, then
-- the old sync of every order that has a stop with a choice or a live bridge: a stop the desk had set direct gets its
-- bridge back, as the rule of 074 wants, and the sync writes via_hub = wanted again); NOT NULL DEFAULT false again;
-- the 107 view; B-95 / B-99 as 074b wrote them (the Greek texts 111 wrote stay: said here, they only describe). The
-- hour columns are dropped only while no stop has an hour; otherwise they stay (nothing reads them without the
-- Worker) and the NOTICE says how many. ASCII only, one DO block.
DO $do$
DECLARE v_o bigint; v_n int := 0; v_h int; v_orders bigint[];
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM set_config('statement_timeout', '120s', true);
  PERFORM set_config('search_path', 'public', true);
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'order_stops' AND column_name = 'time_from') THEN
    RAISE EXCEPTION '111 rollback: 111 is not applied - nothing to do';
  END IF;
  CREATE OR REPLACE FUNCTION public.plan_h_bridge_wanted(p_stop bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$
  select coalesce((
    select s.deleted_at is null and coalesce(s.pallets, 0) > 0 and plan_h_vs_nat_side(o.direction, s.stop_type)
       and plan_h_vs_in_v5(o.id)
      from order_stops s join orders o on o.id = s.order_id where s.id = p_stop), false)
$f$;
  CREATE OR REPLACE FUNCTION public.plan_bridge_sync(p_order bigint, p_why text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare
  v_actor text := coalesce(nullif(btrim(p_why), ''), 'trigger:plan_bridge_sync');
  v_role constant text := 'system';
  st record; v_w boolean; v_sh bigint; v_new int := 0; v_p shipment_pieces%rowtype; v_s shipments%rowtype;
  v_ref text; nl record;
begin
  if plan_cutover_day() is null then return; end if;
  -- a bridge whose stop moved to another order (or lost it) is not this order's any more
  for v_sh in select s.id from shipments s join order_stops os on os.id = s.order_stop_id
               where s.order_id = p_order and s.deleted_at is null and os.order_id is distinct from p_order order by s.id loop
    perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
  end loop;
  for st in select s.id, s.via_hub, s.pallets from order_stops s where s.order_id = p_order order by s.id loop
    v_w := plan_h_bridge_wanted(st.id);
    select id into v_sh from shipments where order_stop_id = st.id and deleted_at is null;
    if v_w and v_sh is null then
      insert into shipments (order_id, order_stop_id, created_by) values (p_order, st.id, v_actor) returning * into v_s;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipments', v_s.id::text, null, to_jsonb(v_s));
      insert into shipment_pieces (shipment_id, pallets, created_by) values (v_s.id, st.pallets, v_actor) returning * into v_p;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipment_pieces', v_p.id::text, null, to_jsonb(v_p));
      v_new := v_new + 1;
    elsif not v_w and v_sh is not null then
      perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
    end if;
    if st.via_hub is distinct from v_w then
      update order_stops set via_hub = v_w where id = st.id;
    end if;
  end loop;
  if v_new > 0 then
    -- every old Direct NL is unlinked, Delivered ones too (owner 28/10: the old national data has no business value
    -- and never blocks v5 - an old VS moved onto day L or later takes the normal bridge path); its id stays in
    -- plan_cutover_log and the soft delete is audited
    select coalesce(reference, id::text) into v_ref from orders where id = p_order;
    for nl in update national_loads set deleted_at = now()
               where source_order_id = p_order and source_type = 'Direct' and deleted_at is null
               returning id, legacy_id, truck_id, partner_id, status loop
      insert into plan_cutover_log (kind, table_name, row_id, reason, before_data)
      values ('nl_unlinked', 'national_loads', nl.id, v_actor,
              jsonb_build_object('order_id', p_order, 'truck_id', nl.truck_id, 'partner_id', nl.partner_id, 'status', nl.status));
      perform plan_h_audit(v_actor, v_role, 'delete', 'national_loads', coalesce(nl.legacy_id, nl.id::text),
                           jsonb_build_object('deleted_at', null), jsonb_build_object('deleted_at', now(), 'reason', 'v5 bridge (074)'));
      -- Q-3: the desk re-records in v5 every unlinked load that was already moving - a vehicle on it, or a status past
      -- Pending (a Friday export Delivered at Veroia with no truck on the record); a Cancelled load has nothing to re-record
      if nl.status is distinct from 'Cancelled'
         and (nl.truck_id is not null or nl.partner_id is not null or nl.status is distinct from 'Pending') then
        -- "I VS %s perase sto neo board; to palio ethniko fortio eiche ochima (%s): anathese tin xana"
        perform plan_h_notice('natl', 'legacy_nl_replaced',
          'zpcgVlMgJXMgz4DOrc+BzrHPg861IM+Dz4TOvyDOvc6tzr8gYm9hcmTCtyDPhM6/IM+AzrHOu865z4wgzrXOuM69zrnOus+MIM+Gzr/Pgc+Ezq/OvyDOtc6vz4fOtSDPjM+HzrfOvM6xICglcyk6IM6xzr3OrM64zrXPg86tIM+EzrfOvSDOvs6xzr3OrA==',
          array[v_ref, coalesce('truck ' || nl.truck_id, 'partner ' || nl.partner_id, 'status ' || coalesce(nl.status, '-'))],
          p_order, null, null, v_actor, v_role);
      end if;
    end loop;
  end if;
end
$f$;
  CREATE OR REPLACE FUNCTION public.plan_bridge_on_stop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare v_sh bigint; v_o orders%rowtype;
begin
  if plan_cutover_day() is null then return null; end if;
  if new.order_id is null and (tg_op = 'INSERT' or old.order_id is null) then return null; end if;
  -- the common case first, as plan_bridge_on_order: a stop of an order that is not a VS and has no bridge, written
  -- without via_hub, is not the bridge's (a non-VS stop WITH via_hub is set back by the sync, B-99's rule)
  if (tg_op = 'INSERT' or old.order_id is not distinct from new.order_id) and not new.via_hub
     and not exists (select 1 from orders o where o.id = new.order_id and o.veroia_switch)
     and not exists (select 1 from shipments s where s.order_id = new.order_id and s.deleted_at is null) then
    return null;
  end if;
  if tg_op = 'UPDATE' then
    select id into v_sh from shipments where order_stop_id = new.id and deleted_at is null;
    if v_sh is not null and new.order_id is not distinct from old.order_id and new.deleted_at is null then
      if old.location_id is distinct from new.location_id and current_setting('plan.writer', true) is distinct from 'natl' then
        perform plan_h_bridge_place(new.id, old.location_id, new.location_id, 'trigger:plan_bridge_sync', 'system');
      end if;
      if old.pallets is distinct from new.pallets then
        perform plan_h_bridge_recut(v_sh, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
      select * into v_o from orders where id = new.order_id;
      if old.datetime is distinct from new.datetime and current_setting('plan.writer', true) is distinct from 'natl'
         and plan_h_vs_nat_side(v_o.direction, new.stop_type) then
        perform plan_h_bridge_unplan(new.order_id, new.id, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
    end if;
    if old.order_id is not null and old.order_id is distinct from new.order_id then
      perform plan_bridge_sync(old.order_id, 'trigger:plan_bridge_sync');
    end if;
  end if;
  if new.order_id is not null then perform plan_bridge_sync(new.order_id, 'trigger:plan_bridge_sync'); end if;
  return null;
end
$f$;
  CREATE OR REPLACE FUNCTION public.pl_h_delivery_write(p_order bigint, p_stop bigint, p_why text) RETURNS int
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
  DECLARE
    v_o orders%ROWTYPE; v_s record; v_day date; v_new pl_movements%ROWTYPE; v_n int := 0;
  BEGIN
    SELECT * INTO v_o FROM orders WHERE id = p_order;
    IF NOT FOUND OR v_o.deleted_at IS NOT NULL OR v_o.status IS DISTINCT FROM 'Delivered' OR v_o.pallet_exchange IS NOT TRUE THEN
      RETURN 0;
    END IF;
    -- the browser feeder's exceptions (core/pallet-feed.js plOrderGate)
    IF v_o.parent_order_id IS NOT NULL THEN RETURN 0; END IF;
    IF EXISTS (SELECT 1 FROM stock_lots WHERE order_id = p_order AND deleted_at IS NULL) THEN RETURN 0; END IF;
    -- no client = no counterparty (one_counterparty CHECK): skipped, never a failed save; the stop stays in
    -- pl_v_missing_delivery, where the accountant and the auditor see it
    IF v_o.client_id IS NULL THEN RETURN 0; END IF;
    v_day := (now() AT TIME ZONE 'Europe/Athens')::date;
    FOR v_s IN SELECT id, location_id, round(pallets)::int AS pallets, datetime FROM order_stops
                -- whole pallets as 107's list shows them (round): a stop the list calls "0 pal." is not written
                WHERE order_id = p_order AND stop_type = 'Unloading' AND deleted_at IS NULL AND round(coalesce(pallets, 0)) >= 1
                  AND (p_stop IS NULL OR id = p_stop)
                ORDER BY id LOOP
      v_new := NULL;
      INSERT INTO pl_movements (movement_date, counterparty_type, client_id, location_id, event_type, taken, given,
                                order_stop_id, order_id, status, created_by, confirmed_by, confirmed_at)
      VALUES (CASE WHEN p_why = 'status' THEN v_day ELSE coalesce(v_o.actual_delivery_date, v_s.datetime, v_day) END,
              'CLIENT', v_o.client_id, v_s.location_id, 'DELIVERY', v_s.pallets, v_s.pallets,
              v_s.id, p_order, 'confirmed', 'system', 'system', now())
      ON CONFLICT (order_stop_id, event_type)
        WHERE order_stop_id IS NOT NULL AND status <> 'reversed' AND event_type = ANY (ARRAY['LOADING'::text, 'DELIVERY'::text])
        DO NOTHING
      RETURNING * INTO v_new;
      IF v_new.id IS NOT NULL THEN
        PERFORM plan_h_audit('system', 'system', 'create', 'pl_movements', v_new.id::text, NULL,
          to_jsonb(v_new) || jsonb_build_object('source', 'trigger:108', 'why', p_why));
        v_n := v_n + 1;
      END IF;
    END LOOP;
    RETURN v_n;
  END $f$;
  DROP TRIGGER plan_bridge_on_stop ON public.order_stops;
  CREATE TRIGGER plan_bridge_on_stop AFTER INSERT OR UPDATE OF location_id, pallets, deleted_at, stop_type, datetime, order_id
    ON public.order_stops FOR EACH ROW EXECUTE FUNCTION public.plan_bridge_on_stop();
  CREATE OR REPLACE VIEW public.pl_v_missing_delivery WITH (security_invoker = true) AS
  SELECT s.id AS order_stop_id, o.id AS order_id, o.direction,
         o.client_id, c.company_name AS client_name,
         s.location_id, l.name AS location_name, l.city AS location_city, l.country AS location_country,
         round(s.pallets)::int AS pallets, s.datetime AS stop_date, o.delivery_datetime, o.actual_delivery_date,
         coalesce(o.actual_delivery_date, s.datetime, o.delivery_datetime) AS delivered_on,
         (SELECT count(*) FROM public.order_stops u
           WHERE u.order_id = o.id AND u.stop_type = 'Unloading' AND u.deleted_at IS NULL AND coalesce(u.pallets, 0) > 0)::int AS unloading_stops,
         EXISTS (SELECT 1 FROM public.shipments sh WHERE sh.order_id = o.id AND sh.deleted_at IS NULL) AS has_nat_leg
    FROM public.orders o
    JOIN public.order_stops s ON s.order_id = o.id AND s.deleted_at IS NULL AND s.stop_type = 'Unloading' AND coalesce(s.pallets, 0) > 0
    LEFT JOIN public.clients c ON c.id = o.client_id
    LEFT JOIN public.locations l ON l.id = s.location_id
   WHERE o.deleted_at IS NULL AND o.status = 'Delivered' AND o.pallet_exchange IS TRUE AND o.parent_order_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.stock_lots sl WHERE sl.order_id = o.id AND sl.deleted_at IS NULL)
     AND NOT EXISTS (SELECT 1 FROM public.pl_movements m
                      WHERE m.order_stop_id = s.id AND m.event_type = 'DELIVERY' AND m.status <> 'reversed');
  REVOKE ALL ON public.pl_v_missing_delivery FROM PUBLIC, anon, authenticated;
  GRANT SELECT ON public.pl_v_missing_delivery TO service_role, tms_check_runner;
  -- the orders to re-sync, taken before via_hub is reset: a stop with a choice, or a live bridge
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x), '{}') INTO v_orders FROM (
    SELECT order_id AS x FROM public.order_stops WHERE via_hub IS NOT NULL AND order_id IS NOT NULL
    UNION SELECT order_id FROM public.shipments WHERE deleted_at IS NULL AND order_id IS NOT NULL) u;
  UPDATE public.order_stops SET via_hub = false WHERE via_hub IS DISTINCT FROM false;
  ALTER TABLE public.order_stops ALTER COLUMN via_hub SET DEFAULT false, ALTER COLUMN via_hub SET NOT NULL;
  FOREACH v_o IN ARRAY v_orders LOOP
    PERFORM public.plan_bridge_sync(v_o, '111 rollback');
    v_n := v_n + 1;
  END LOOP;
  COMMENT ON COLUMN public.order_stops.via_hub IS NULL;
  UPDATE monitoring.checks SET sql_text = 'SELECT count(*) FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback''))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL) OR s.via_hub <> (o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback'')))))', ids_sql = 'SELECT coalesce(array_agg(x ORDER BY x), ''{}'') FROM (SELECT coalesce(o.legacy_id, o.id::text) AS x FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback''))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL) OR s.via_hub <> (o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback''))))) ORDER BY 1 LIMIT 50) s' WHERE id = 'B-95';
  UPDATE monitoring.checks SET sql_text = 'SELECT count(*) FROM order_stops s JOIN orders o ON o.id = s.order_id WHERE s.via_hub AND (o.veroia_switch IS NOT TRUE OR o.deleted_at IS NOT NULL OR NOT coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false))', ids_sql = 'SELECT coalesce(array_agg(x ORDER BY x), ''{}'') FROM (SELECT coalesce(s.legacy_id, s.id::text) AS x FROM order_stops s JOIN orders o ON o.id = s.order_id WHERE s.via_hub AND (o.veroia_switch IS NOT TRUE OR o.deleted_at IS NOT NULL OR NOT coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false)) ORDER BY 1 LIMIT 50) s' WHERE id = 'B-99';
  IF (SELECT count(*) FROM monitoring.checks WHERE (id = 'B-95' AND md5(sql_text) = 'f255e0226bc9378644f86bcb533d4a69' AND md5(ids_sql) = '70eb6d174a4ab69dd3f5bb4127cc9b52')
                                              OR (id = 'B-99' AND md5(sql_text) = 'df11dab3bee7650c32d3cc41070ec4d6' AND md5(ids_sql) = '54aac1f418680ee5bc1136c92c247852')) <> 2 THEN
    RAISE EXCEPTION '111 rollback: B-95 / B-99 did not come back to 074b''s text';
  END IF;
  SELECT count(*) INTO v_h FROM public.order_stops WHERE time_from IS NOT NULL OR time_to IS NOT NULL;
  IF v_h = 0 THEN
    ALTER TABLE public.order_stops DROP CONSTRAINT order_stops_time_from_fmt, DROP CONSTRAINT order_stops_time_to_fmt,
      DROP COLUMN time_from, DROP COLUMN time_to;
  END IF;
  RAISE NOTICE '111 ROLLBACK OK: old bodies, trigger, view, B-95 / B-99 back; % orders re-synced; hour columns %', v_n,
    CASE WHEN v_h = 0 THEN 'dropped (empty)' ELSE 'KEPT: ' || v_h || ' stops have an hour' END;
END
$do$;
